$arUser = $rsUser->Fetch();
global $myphoneNumber;
$myphoneNumber = $arUser["PERSONAL_PHONE"];
$isAuthorized = $USER->IsAuthorized();

$projectId = (int)($_GET['id'] ?? 0);
$project = $projectId > 0
    ? \CIBlockElement::GetList([], ['IBLOCK_ID' => PROJECTS_IBLOCK_ID, 'ID' => $projectId, 'ACTIVE' => 'Y'], false, false, ['ID', 'NAME'])->Fetch()
    : null;

