    <?
    require($_SERVER['DOCUMENT_ROOT'] . '/bitrix/footer.php');
    exit;
}

$projectSettlementId = '';
$projectCrestFileId = 0;
$projectProps = \CIBlockElement::GetProperty(PROJECTS_IBLOCK_ID, $projectId, []);
while ($prop = $projectProps->Fetch()) {
    if ($prop['CODE'] === 'PR_LOCATION_SETTLEMENT') {
        $projectSettlementId = (string)$prop['VALUE'];
    } elseif ($prop['CODE'] === 'PR_CITY_COAT') {
        $projectCrestFileId = (int)$prop['VALUE'];
    }
}
$projectSettlementName = function_exists('getGeoSettlementName') ? getGeoSettlementName($projectSettlementId) : '';
$projectCrestPath = function_exists('getGeoSettlementCoatPath') ? getGeoSettlementCoatPath($projectSettlementId) : '';
if (!$projectCrestPath && $projectCrestFileId) {
    $projectCrestPath = CFile::GetPath($projectCrestFileId);
}
